from dataclasses import dataclass

@dataclass(frozen=True)
class Actor:
    user_id: str
    account_ids: frozenset[str]

def authorize_export(actor: Actor, requested_account_id: str) -> None:
    if requested_account_id not in actor.account_ids:
        raise PermissionError('actor is not allowed to export this account')
